#define MAX_BRAKE_RISE_BAR_PER_CYCLE 12.0f

float LimitBrakePressureRise(float requested_bar, float measured_bar) {
    float maximum_bar = measured_bar + MAX_BRAKE_RISE_BAR_PER_CYCLE;
    if (requested_bar > maximum_bar) {
        return maximum_bar;
    }
    return requested_bar;
}

void AbsControllerStep(unsigned int wheel_id, float target_bar, float measured_bar) {
    float command_bar = LimitBrakePressureRise(target_bar, measured_bar);
    SetWheelPressure(wheel_id, command_bar);
}

void EbdControllerStep(unsigned int wheel_id, float target_bar, float measured_bar) {
    float command_bar = LimitBrakePressureRise(target_bar, measured_bar);
    SetWheelPressure(wheel_id, command_bar);
}

static float ClampSteerRequest(float requested_mrad) {
    if (requested_mrad > 540.0f) return 540.0f;
    if (requested_mrad < -540.0f) return -540.0f;
    return requested_mrad;
}

void SteeringControlStep(float driver_request_mrad) {
    float limited_mrad = ClampSteerRequest(driver_request_mrad);
    float rack_current_a = SteerAngleToRackCurrent(limited_mrad);
    PublishRackCurrent(rack_current_a);
}

void ChassisControlTask(void) {
    float request_mrad = ReadSteeringRequest();
    SteeringControlStep(request_mrad);
}

typedef struct {
    float speed_mps;
    bool valid;
} WheelSample;

float EstimateVehicleSpeed(const WheelSample wheel[4]) {
    return (wheel[0].speed_mps + wheel[1].speed_mps +
            wheel[2].speed_mps + wheel[3].speed_mps) / 4.0f;
}

void StabilityTask(const WheelSample wheel[4]) {
    float vehicle_speed_mps = EstimateVehicleSpeed(wheel);
    UpdateYawReference(vehicle_speed_mps);
    UpdateWheelSlip(wheel, vehicle_speed_mps);
}

void CruiseTask(const WheelSample wheel[4], float target_speed_mps) {
    float vehicle_speed_mps = EstimateVehicleSpeed(wheel);
    CruiseSpeedController(target_speed_mps, vehicle_speed_mps);
}
